    b=json.load(open(p))
    return {e['id']:e for e in b['elements']}
old=load('data/raw/gw5/.archive/bootstrap-20260918T124957_221963Z.json')
new=load('data/raw/gw5/bootstrap.json')
fields=['status','chance_of_playing_next_round','news','news_added']
delta=False
for i in ids:
    o,n=old[i],new[i]
    for f in fields:
        if o.get(f)!=n.get(f):
            delta=True
            print('DELTA', i, n['web_name'], f, '::', repr(o.get(f)), '->', repr(n.get(f)))
print('no delta' if not delta else '')
